<?php
declare(strict_types=1);ob_start();session_start();require dirname(__DIR__,2).'/config/config.php';
function rc_json(int $status,array $body):never{http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');if(ob_get_level())ob_clean();echo json_encode($body,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE);exit;}
function rc_ok(string $message,array $data=[]):never{rc_json(200,['ok'=>true,'message'=>$message,'data'=>$data]);}
if(!signed_in())rc_json(401,['ok'=>false,'message'=>'Your session expired. Sign in again.']);require_sign_in();if(!empty($_SESSION['must_change_password']))rc_json(403,['ok'=>false,'message'=>'Change your password before continuing.']);
$role=(string)$_SESSION['role'];$manager=in_array($role,['admin','director','sub_director','headteacher'],true);$commentRoles=['teacher','assistant_academic','head_academic','examination_officer'];if(!$manager&&!in_array($role,$commentRoles,true))rc_json(403,['ok'=>false,'message'=>'Your role cannot manage report cards.']);$uid=(int)$_SESSION['user_id'];$school=filter_var($_REQUEST['school_id']??null,FILTER_VALIDATE_INT);$pupil=(int)($_REQUEST['pupil_id']??0);$year=filter_var($_REQUEST['academic_year']??null,FILTER_VALIDATE_INT);$term=trim((string)($_REQUEST['term']??''));if(!$school||!$pupil||$year===false||$year<2000||$year>2100||mb_strlen($term)>40)rc_json(422,['ok'=>false,'message'=>'Choose a school, pupil, academic year, and valid term.']);$db=db();$q=$db->prepare('SELECT 1 FROM school_memberships WHERE user_id=? AND school_id=?');$q->execute([$uid,$school]);if(!$q->fetchColumn())rc_json(403,['ok'=>false,'message'=>'That school is outside your access.']);
function rc_results_exist(PDO $db,int $school,int $pupil,int $year,string $term):bool{$q=$db->prepare("SELECT 1 FROM pupil_results r JOIN school_exams x ON x.school_id=r.school_id AND x.name=r.exam_name AND x.academic_year=r.academic_year AND x.status='results_published' AND (x.class_id IS NULL OR x.class_id IN (SELECT c.id FROM school_classes c WHERE c.school_id=r.school_id AND c.name=r.class_level)) AND (x.subject_id IS NULL OR x.subject_id IN (SELECT s.id FROM school_class_subjects s JOIN school_classes c ON c.id=s.class_id WHERE c.school_id=r.school_id AND c.name=r.class_level AND s.name=r.subject)) WHERE r.school_id=? AND r.pupil_id=? AND r.academic_year=? AND COALESCE(x.term,'')=? LIMIT 1");$q->execute([$school,$pupil,$year,$term]);return(bool)$q->fetchColumn();}
function rc_teacher_scope(PDO $db,int $uid,int $school,int $pupil,int $year,string $term):bool{$q=$db->prepare("SELECT 1 FROM pupil_results r JOIN school_exams x ON x.school_id=r.school_id AND x.name=r.exam_name AND x.academic_year=r.academic_year AND x.status='results_published' AND (x.class_id IS NULL OR x.class_id IN (SELECT c.id FROM school_classes c WHERE c.school_id=r.school_id AND c.name=r.class_level)) AND (x.subject_id IS NULL OR x.subject_id IN (SELECT s.id FROM school_class_subjects s JOIN school_classes c ON c.id=s.class_id WHERE c.school_id=r.school_id AND c.name=r.class_level AND s.name=r.subject)) WHERE r.school_id=? AND r.pupil_id=? AND r.academic_year=? AND COALESCE(x.term,'')=? AND (EXISTS(SELECT 1 FROM teacher_assignments a WHERE a.user_id=? AND a.school_id=r.school_id AND a.class_level=r.class_level AND a.subject=r.subject AND a.active=1) OR EXISTS(SELECT 1 FROM result_delegations d WHERE d.user_id=? AND d.school_id=r.school_id AND d.academic_year=r.academic_year AND d.active=1 AND (d.class_level IS NULL OR d.class_level=r.class_level))) LIMIT 1");$q->execute([$school,$pupil,$year,$term,$uid,$uid]);return(bool)$q->fetchColumn();}
if($_SERVER['REQUEST_METHOD']!=='POST')rc_json(405,['ok'=>false,'message'=>'Method not allowed.']);if(!hash_equals($_SESSION['csrf']??'',(string)($_SERVER['HTTP_X_CSRF_TOKEN']??$_POST['csrf']??'')))rc_json(400,['ok'=>false,'message'=>'Your session expired. Refresh and try again.']);$action=(string)($_POST['action']??'');
try{
 if($action==='save_comment'){$type=(string)($_POST['comment_type']??'');$comment=trim((string)($_POST['comment']??''));if(!in_array($type,['teacher','headteacher'],true)||mb_strlen($comment)>4000)throw new DomainException('Choose a comment section and enter no more than 4000 characters.');if($type==='headteacher'&&!$manager)rc_json(403,['ok'=>false,'message'=>'Only school leadership can write the headteacher comment.']);$q=$db->prepare('SELECT id,class_level FROM pupils WHERE id=? AND school_id=?');$q->execute([$pupil,$school]);$student=$q->fetch();if(!$student)throw new DomainException('Pupil not found in this school.');if(!$manager&&!rc_teacher_scope($db,$uid,$school,$pupil,(int)$year,$term))rc_json(403,['ok'=>false,'message'=>'Teacher comments are limited to pupils with published results in your assigned class and subject.']);if(!rc_results_exist($db,$school,$pupil,(int)$year,$term))throw new DomainException('A report card requires at least one published result for this pupil, year, and term.');$db->beginTransaction();$q=$db->prepare('SELECT * FROM pupil_report_cards WHERE school_id=? AND pupil_id=? AND academic_year=? AND term=? FOR UPDATE');$q->execute([$school,$pupil,$year,$term]);$card=$q->fetch();if(!$card){$q=$db->prepare('INSERT INTO pupil_report_cards(school_id,pupil_id,academic_year,term,created_by,updated_by) VALUES(?,?,?,?,?,?)');$q->execute([$school,$pupil,$year,$term,$uid,$uid]);$id=(int)$db->lastInsertId();$oldStatus='new';}else{$id=(int)$card['id'];$oldStatus=$card['status'];}
  if($type==='teacher'){$q=$db->prepare("UPDATE pupil_report_cards SET teacher_comment=?,teacher_comment_by=?,teacher_comment_at=CURRENT_TIMESTAMP,status='draft',published_by=NULL,published_at=NULL,updated_by=? WHERE id=? AND school_id=?");$event='save_teacher_comment';}else{$q=$db->prepare("UPDATE pupil_report_cards SET headteacher_comment=?,headteacher_comment_by=?,headteacher_comment_at=CURRENT_TIMESTAMP,status='draft',published_by=NULL,published_at=NULL,updated_by=? WHERE id=? AND school_id=?");$event='save_headteacher_comment';}$q->execute([$comment?:null,$uid,$uid,$id,$school]);$q=$db->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)');$q->execute([$uid,$event,'pupil_report_card',$id,json_encode(['school_id'=>$school,'pupil_id'=>$pupil,'academic_year'=>$year,'term'=>$term,'previous_status'=>$oldStatus],JSON_THROW_ON_ERROR)]);$db->commit();rc_ok('Comment saved. The report card is in draft until school leadership republishes it.',['id'=>$id]);}
 if($action==='publish'){$id=(int)($_POST['report_card_id']??0);if(!$manager)rc_json(403,['ok'=>false,'message'=>'Only school leadership can publish report cards.']);$db->beginTransaction();$q=$db->prepare('SELECT * FROM pupil_report_cards WHERE id=? AND school_id=? AND pupil_id=? AND academic_year=? AND term=? FOR UPDATE');$q->execute([$id,$school,$pupil,$year,$term]);$card=$q->fetch();if(!$card)throw new DomainException('Report card not found in this school.');if(!$card['teacher_comment']&&!$card['headteacher_comment'])throw new DomainException('Add a teacher or headteacher comment before publishing.');if(!rc_results_exist($db,$school,$pupil,(int)$year,$term))throw new DomainException('Published results are no longer available for this report card.');$db->prepare("UPDATE pupil_report_cards SET status='published',published_by=?,published_at=CURRENT_TIMESTAMP,updated_by=? WHERE id=? AND school_id=?")->execute([$uid,$uid,$id,$school]);$q=$db->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)');$q->execute([$uid,'publish','pupil_report_card',$id,json_encode(['school_id'=>$school,'pupil_id'=>$pupil,'academic_year'=>$year,'term'=>$term],JSON_THROW_ON_ERROR)]);$db->commit();rc_ok('Report card published to the parent and pupil portals.',['id'=>$id]);}
 throw new DomainException('Choose a supported report-card action.');
}catch(DomainException $e){if($db->inTransaction())$db->rollBack();rc_json(422,['ok'=>false,'message'=>$e->getMessage()]);}catch(PDOException $e){if($db->inTransaction())$db->rollBack();error_log('Report-card database error: '.$e->getMessage());rc_json(500,['ok'=>false,'message'=>'The report card could not be saved. Verify its migration.']);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log('Report-card request error: '.$e->getMessage());rc_json(500,['ok'=>false,'message'=>'The report-card request could not be completed.']);}
